                new UuidNullableProjection(ReadFieldUuidNullable(node)),
            _ => throw GraphReads.NotACase(node, "UuidNullableProjection"),
        };
    }

    internal static int WriteUuidProjection(GraphBuilder graph, UuidProjection value)
    {
        return value.Value switch
        {
            AsUuidUuidProjection item => WriteAsUuidUuidProjection(graph, item),
            IfUuidProjection item => WriteIfUuidProjection(graph, item),
            CoalesceUuidProjection item => WriteCoalesceUuidProjection(graph, item),
            GreatestUuidProjection item => WriteGreatestUuidProjection(graph, item),
            LeastUuidProjection item => WriteLeastUuidProjection(graph, item),
            MinUuidProjection item => WriteMinUuidProjection(graph, item),
            MaxUuidProjection item => WriteMaxUuidProjection(graph, item),
            FirstUuidProjection item => WriteFirstUuidProjection(graph, item),
            LastUuidProjection item => WriteLastUuidProjection(graph, item),
            PercentileDiscreteUuidProjection item => WritePercentileDiscreteUuidProjection(graph, item),
            ModeUuidProjection item => WriteModeUuidProjection(graph, item),
            PreviousUuidProjection item => WritePreviousUuidProjection(graph, item),
            NextUuidProjection item => WriteNextUuidProjection(graph, item),
            LiteralUuid item => WriteLiteralUuid(graph, item),
            ParamUuid item => WriteParamUuid(graph, item),
            FieldUuid item => WriteFieldUuid(graph, item),
            _ => throw GraphBuilder.Empty("UuidProjection"),
        };
    }

    internal static UuidProjection ReadUuidProjection(IReadNode node)
    {
        return node.Label switch
        {
            "AsUuidUuidProjection" => new UuidProjection(ReadAsUuidUuidProjection(node)),
            "IfUuidProjection" => new UuidProjection(ReadIfUuidProjection(node)),
            "CoalesceUuidProjection" =>
                new UuidProjection(ReadCoalesceUuidProjection(node)),
            "GreatestUuidProjection" =>
                new UuidProjection(ReadGreatestUuidProjection(node)),
            "LeastUuidProjection" => new UuidProjection(ReadLeastUuidProjection(node)),
            "MinUuidProjection" => new UuidProjection(ReadMinUuidProjection(node)),
            "MaxUuidProjection" => new UuidProjection(ReadMaxUuidProjection(node)),
            "FirstUuidProjection" => new UuidProjection(ReadFirstUuidProjection(node)),
            "LastUuidProjection" => new UuidProjection(ReadLastUuidProjection(node)),
            "PercentileDiscreteUuidProjection" =>
                new UuidProjection(ReadPercentileDiscreteUuidProjection(node)),
            "ModeUuidProjection" => new UuidProjection(ReadModeUuidProjection(node)),
            "PreviousUuidProjection" =>
                new UuidProjection(ReadPreviousUuidProjection(node)),
            "NextUuidProjection" => new UuidProjection(ReadNextUuidProjection(node)),
            "LiteralUuid" => new UuidProjection(ReadLiteralUuid(node)),
            "ParamUuid" => new UuidProjection(ReadParamUuid(node)),
            "FieldUuid" => new UuidProjection(ReadFieldUuid(node)),
            _ => throw GraphReads.NotACase(node, "UuidProjection"),
        };
    }
}
